      out[key] = source[key];
    }
  }
  return out;
}

export function mergeLayers(defaults, file, env) {
  const base = isPlainObject(defaults) ? defaults : {};
  const fileLayer = isPlainObject(file) ? file : {};
  const envLayer = isPlainObject(env) ? env : {};

  const network = {
    ...pick(base.network, ['endpoint', 'retries']),
    ...pick(fileLayer.network, ['endpoint', 'retries']),
    ...pick(envLayer.network, ['endpoint', 'retries']),
  };
  const ui = {
    ...pick(base.ui, ['theme', 'compact']),
    ...pick(fileLayer.ui, ['theme', 'compact']),
    ...pick(envLayer.ui, ['theme', 'compact']),
  };
  const enabled = [
    pick(base, ['enabled']),
    pick(fileLayer, ['enabled']),
    pick(envLayer, ['enabled']),
  ].reduce((acc, layer) => (Object.prototype.hasOwnProperty.call(layer, 'enabled') ? layer.enabled : acc), undefined);

  return { network, ui, enabled };
}
